import io, json, base64, os
from flask import Flask, request, send_file, Response, redirect
from openpyxl import load_workbook
from openpyxl import Workbook
from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
from openpyxl.utils import get_column_letter

app = Flask(__name__)

TEMPLATE_B64 = ""

# ── PRESS APPROVAL Excel ─────────────────────────────────────────────────────

DOT_ROWS = [0,3,"5 lam",10,20,25,30,40,45,"50 lam",60,70,75,80,"lamination",100]
PULL_ROWS = [(9,10,13,14,15),(19,20,23,24,25),(29,30,33,34,35),(39,40,43,44,45),(49,50,53,54,55),(58,59,62,63,64)]

def fill_press_approval(data):
    wb = load_workbook(io.BytesIO(base64.b64decode(TEMPLATE_B64)))
    ws = wb["Overview"]
    ws["B8"]=data.get("date",""); ws["B9"]=data.get("time","")
    ws["B11"]=data.get("printer",""); ws["B13"]=data.get("printerAddress","")
    ws["G11"]=data.get("printerAttendee",""); ws["G12"]=data.get("sgkAttendee",""); ws["G13"]=data.get("clientAttendee","")
    ws["B20"]=data.get("brand",""); ws["B21"]=data.get("variant","")
    ws["G20"]=data.get("clientProductRef",""); ws["G21"]=data.get("sgkJobNumber","")
    ws["B26"]=data.get("notes",""); ws["B36"]=data.get("jobPreview","")
    ws2=wb["On Press"]
    for rows in PULL_ROWS:
        ws2.cell(row=rows[0],column=2).value=None; ws2.cell(row=rows[1],column=2).value=None
        for j in range(3): ws2.cell(row=rows[2+j],column=2).value=None
    for i,pull in enumerate(data.get("pulls",[])[:6]):
        rows=PULL_ROWS[i]
        ws2.cell(row=rows[0],column=2).value=pull.get("time","")
        ws2.cell(row=rows[1],column=2).value=pull.get("comments","")
        adjs=pull.get("adjustments",["","",""])
        for j in range(3): ws2.cell(row=rows[2+j],column=2).value=adjs[j] if j<len(adjs) else ""
    ap=data.get("approvedPull")
    ws2["B68"]=(ap+1) if ap is not None else ""; ws2["B69"]=data.get("approvalTime",""); ws2["B70"]=data.get("approvalComments","")
    ws3=wb["Print Sample Analysis"]
    ws3["B8"]=data.get("printSampleComments",""); ws3["B20"]=data.get("issuesAnalysis",""); ws3["B32"]=data.get("improvements","")
    colors=data.get("colors",[]); dotgain=data.get("dotgain",{}); density=data.get("density",{}); lab=data.get("lab",{})
    for r in range(43,64):
        for c in range(3,9): ws3.cell(row=r,column=c).value=None
    for ci,color in enumerate(colors):
        col=3+ci; cell=ws3.cell(row=43,column=col); cell.value=color["label"]
        hex_col=color["hex"].lstrip("#")
        if len(hex_col)==6:
            try: cell.fill=PatternFill("solid",fgColor="FF"+hex_col.upper())
            except: pass
        cell.font=Font(bold=True,size=12); cell.alignment=Alignment(horizontal="center",vertical="center")
    for ri,linear in enumerate(DOT_ROWS):
        for ci,color in enumerate(colors):
            vals=dotgain.get(color["id"],[])
            ws3.cell(row=44+ri,column=3+ci).value=vals[ri] if ri<len(vals) and vals[ri]!="" else None
    for ci,color in enumerate(colors):
        ws3.cell(row=60,column=3+ci).value=density.get(color["id"],"") or None
        lab_c=lab.get(color["id"],{})
        ws3.cell(row=61,column=3+ci).value=lab_c.get("L","") or None
        ws3.cell(row=62,column=3+ci).value=lab_c.get("a","") or None
        ws3.cell(row=63,column=3+ci).value=lab_c.get("b","") or None
    buf=io.BytesIO(); wb.save(buf); return buf.getvalue()

# ── MAKEREADY Excel ──────────────────────────────────────────────────────────

def fill_makeready(data):
    wb=Workbook(); ws=wb.active; ws.title="Makeready Checklist"
    DARK="1A1A24"; ACCENT="E8C84A"; SEC_BG="1E1E2A"; HDR_BG="2A2A3A"
    OK_FG="2D9E6A"; OK_BG="1A3D2A"; NOK_FG="D94040"; NOK_BG="3D1A1A"
    WHITE="E8E8F0"; MUTED="9898B0"; BORDER_C="2A2A36"
    def fnt(bold=False,sz=11,color=WHITE): return Font(bold=bold,size=sz,color=color,name="Calibri")
    def fill(rgb): return PatternFill("solid",fgColor=rgb)
    def aln(h="left",wrap=False): return Alignment(horizontal=h,vertical="center",wrap_text=wrap)
    def brd(clr=BORDER_C):
        s=Side(style="thin",color=clr); return Border(top=s,bottom=s,left=s,right=s)
    for i,w in enumerate([22,16,12,24,16,10,14],1):
        ws.column_dimensions[get_column_letter(i)].width=w
    row=[1]
    def r(): return row[0]
    def nr(h=18): ws.row_dimensions[row[0]].height=h; row[0]+=1
    def mg(r1,r2,c1,c2): ws.merge_cells(start_row=r1,start_column=c1,end_row=r2,end_column=c2)
    def sc(rr,cc,val,**k):
        c=ws.cell(row=rr,column=cc,value=val if val is not None else "")
        for attr in ["font","fill","alignment","border"]:
            if attr in k: setattr(c,attr,k[attr])
    for c in range(1,8): sc(r(),c,"",fill=fill(HDR_BG))
    sc(r(),1,"SGK · MAKEREADY CHECKLIST",font=fnt(True,16,ACCENT),fill=fill(HDR_BG),alignment=aln("left"))
    sc(r(),6,data.get("date",""),font=fnt(False,11,MUTED),fill=fill(HDR_BG),alignment=aln("right"))
    mg(r(),r(),1,5); mg(r(),r(),6,7); nr(28)
    for c in range(1,8): sc(r(),c,"",fill=fill(ACCENT))
    mg(r(),r(),1,7); nr(3)
    def spacer():
        for c in range(1,8): sc(r(),c,"",fill=fill(DARK))
        mg(r(),r(),1,7); nr(6)
    def section(title):
        for c in range(1,8): sc(r(),c,"",fill=fill(SEC_BG))
        sc(r(),1,title,font=fnt(True,11,ACCENT),fill=fill(SEC_BG),alignment=aln("left"),border=brd(SEC_BG))
        mg(r(),r(),1,7); nr(20)
    def label_row(label,value,status=None):
        sc(r(),1,label,font=fnt(False,10,MUTED),fill=fill(DARK),alignment=aln("left"),border=brd())
        for c in [2,3]: sc(r(),c,"",fill=fill(DARK),border=brd())
        mg(r(),r(),1,3)
        sc(r(),4,value or "—",font=fnt(False,11,WHITE),fill=fill(DARK),alignment=aln("left",True),border=brd())
        for c in [5,6]: sc(r(),c,"",fill=fill(DARK),border=brd())
        mg(r(),r(),4,6)
        if status is True: sc(r(),7,"✓  OK",font=fnt(True,10,OK_FG),fill=fill(OK_BG),alignment=aln("center"),border=brd(OK_FG))
        elif status is False: sc(r(),7,"✗  NOK",font=fnt(True,10,NOK_FG),fill=fill(NOK_BG),alignment=aln("center"),border=brd(NOK_FG))
        else: sc(r(),7,"",fill=fill(DARK),border=brd())
        nr(18)
    def note_row(note):
        if not note: return
        sc(r(),1,"   not:",font=fnt(False,9,MUTED),fill=fill(DARK),alignment=aln("left"),border=brd())
        for c in [2,3]: sc(r(),c,"",fill=fill(DARK),border=brd())
        mg(r(),r(),1,3)
        sc(r(),4,note,font=fnt(False,10,MUTED),fill=fill(DARK),alignment=aln("left",True),border=brd())
        for c in [5,6,7]: sc(r(),c,"",fill=fill(DARK),border=brd())
        mg(r(),r(),4,7); nr(16)
    spacer()
    job=data.get("job",{}); history=data.get("history",{}); colors=data.get("colors",{})
    supplier=data.get("supplier",{}); client=data.get("client",{}); result_d=data.get("result",{})
    section("1.  İŞ BİLGİLERİ")
    for lbl,key in [("Marka","brand"),("Variant","variant"),("Job No","jobNo"),("Tedarikçi","supplier"),("Baskı Tekniği","technique"),("Substrate","substrate"),("SGK Attendee","sgkAttendee")]:
        label_row(lbl,job.get(key))
    spacer()
    section("2.  İŞ GEÇMİŞİ")
    hp=history.get("hasPrevious")
    label_row("Daha önce basıldı mı?","Evet" if hp is True else "Hayır" if hp is False else "—",hp)
    if hp is True:
        rsa=history.get("refSampleAvailable")
        label_row("Referans numune mevcut?","Evet" if rsa is True else "Hayır" if rsa is False else "—",rsa)
        if rsa is True:
            label_row("Numune No",history.get("refSampleNo") or "—")
            label_row("Numune Tarihi",history.get("refSampleDate") or "—")
        mc=history.get("majorChange")
        label_row("Majör değişiklik?","Evet" if mc is True else "Hayır" if mc is False else "—",
                  False if mc is True else True if mc is False else None)
        if mc is True: label_row("Değişiklik açıklaması",history.get("majorChangeDesc") or "—")
        issues=history.get("prevIssues",[])
        if issues:
            section("   Önceki Baskı Sorunları")
            for i,iss in enumerate(issues):
                n=iss.get("notified")
                label_row(f"{i+1}. Sorun",iss.get("note") or "—",True if n is True else False if n is False else None)
    spacer()
    section("3.  RENK REFERANSLARI")
    gp=colors.get("gmgProfile"); gp_name=colors.get("gmgProfileName","")
    gp_val=("Tanımlı"+(f" — {gp_name}" if gp_name else "")) if gp is True else "Tanımsız" if gp is False else "—"
    label_row("GMG / ICC Profili",gp_val,gp)
    spots=colors.get("spotColors",[])
    if spots:
        headers=["Renk Adı","Pantone Kodu","L* a* b*","Tolerans ΔE"]; spans=[(1,2),(3,4),(5,6),(7,7)]
        for (cs,ce),hdr in zip(spans,headers):
            sc(r(),cs,hdr,font=fnt(True,10,ACCENT),fill=fill(SEC_BG),alignment=aln("center"),border=brd())
            if cs!=ce: mg(r(),r(),cs,ce)
        nr(18)
        for spot in spots:
            vals=[spot.get("name","—"),spot.get("pantone","—"),spot.get("lab","—"),spot.get("tolerance","—")]
            for (cs,ce),val in zip(spans,vals):
                sc(r(),cs,val,font=fnt(False,11,WHITE),fill=fill(DARK),alignment=aln("center"),border=brd())
                if cs!=ce: mg(r(),r(),cs,ce)
            nr(18)
    spacer()
    section("4.  TEDARİKÇİ HAZIRLIK")
    sv=supplier.get("substrateConfirmed")
    label_row("Substrate teyit edildi","Evet" if sv is True else "Hayır" if sv is False else "—",sv)
    note_row(supplier.get("substrateNote"))
    tm=supplier.get("techniqueMatch")
    label_row("Baskı tekniği repro ile uyuşuyor","Evet" if tm is True else "Hayır" if tm is False else "—",tm)
    note_row(supplier.get("techniqueNote"))
    ps=supplier.get("proofSent")
    label_row("Proof / referans baskı iletildi","Evet" if ps is True else "Hayır" if ps is False else "—",ps)
    if ps is True: label_row("Proof Durumu",supplier.get("proofStatus","—"))
    note_row(supplier.get("proofSentNote"))
    spacer()
    section("5.  MÜŞTERİ ONAYLARI")
    pa=client.get("proofApproved")
    label_row("Müşteri proof onayı alındı","Evet" if pa is True else "Hayır" if pa is False else "—",pa)
    note_row(client.get("proofApprovedNote"))
    pin=client.get("prevIssuesNotified")
    label_row("Önceki sorunlar müşteriye iletildi","Evet" if pin is True else "Hayır" if pin is False else "—",pin)
    note_row(client.get("prevIssuesNotifiedNote"))
    spacer()
    section("6.  SONUÇ")
    notes=result_d.get("notes","")
    if notes: label_row("Notlar / Gözlemler",notes)
    decision=result_d.get("decision")
    dec_text="✓  BASKIYA HAZIR" if decision=="ready" else "✗  HAZIR DEĞİL" if decision=="notready" else "—  KARAR VERİLMEDİ"
    dec_fg=OK_FG if decision=="ready" else NOK_FG if decision=="notready" else MUTED
    dec_bg=OK_BG if decision=="ready" else NOK_BG if decision=="notready" else DARK
    for c in range(1,8): sc(r(),c,"",fill=fill(dec_bg))
    sc(r(),1,dec_text,font=fnt(True,14,dec_fg),fill=fill(dec_bg),alignment=aln("center"))
    mg(r(),r(),1,7); nr(28); spacer()
    section("KONTROL ÖZETİ")
    checks=[sv,tm,ps,pa,pin,gp,True if hp is False else history.get("refSampleAvailable")]
    filled=[v for v in checks if v is not None]
    ok_c=sum(1 for v in filled if v is True); nok_c=sum(1 for v in filled if v is False); tot=len(filled)
    for (cs,ce),(lbl,val,fg,bg) in zip([(1,2),(3,4),(5,6)],[("✓ OK",ok_c,OK_FG,OK_BG),("✗ NOK",nok_c,NOK_FG,NOK_BG),("Toplam",tot,MUTED,DARK)]):
        sc(r(),cs,f"{lbl}  {val}",font=fnt(True,13,fg),fill=fill(bg),alignment=aln("center"),border=brd(fg))
        mg(r(),r(),cs,ce)
    sc(r(),7,"",fill=fill(DARK)); nr(26)
    buf=io.BytesIO(); wb.save(buf); return buf.getvalue()

